    30  dummySend(UA_Connection *connection, UA_ByteString *buf) {
    31      assert(connection != NULL);
    32      assert(buf != NULL);
    33
    34      if(vBuffer) {
    35          UA_ByteString_deleteMembers(vBuffer);
    36          UA_ByteString_copy(buf, vBuffer);
    37      }
    38      return UA_STATUSCODE_GOOD;
