    52  UA_Connection createDummyConnection(size_t sendBufferSize,
    53                                      UA_ByteString *verificationBuffer) {
    54      vBuffer = verificationBuffer;
    55      UA_ByteString_allocBuffer(&sendBuffer, sendBufferSize);
    56
    57      UA_Connection c;
    58      c.state = UA_CONNECTION_ESTABLISHED;
    59      c.config = UA_ConnectionConfig_default;
    60      c.channel = NULL;
    61      c.sockfd = 0;
    62      c.handle = NULL;
    63      c.incompleteChunk = UA_BYTESTRING_NULL;
    64      c.getSendBuffer = dummyGetSendBuffer;
    65      c.releaseSendBuffer = dummyReleaseSendBuffer;
    66      c.send = dummySend;
    67      c.recv = NULL;
    68      c.releaseRecvBuffer = dummyReleaseRecvBuffer;
    69      c.close = dummyClose;
    70      return c;
    71  }
