    77  UA_StatusCode
    78  UA_Client_recvTesting(UA_Connection *connection, UA_ByteString *response,
    79                      UA_UInt32 timeout) {
    80
    81      if(UA_Client_recvTesting_result != UA_STATUSCODE_GOOD) {
    82          UA_StatusCode temp = UA_Client_recvTesting_result;
    83          UA_Client_recvTesting_result = UA_STATUSCODE_GOOD;
    84          UA_fakeSleep(timeout);
    85          return temp;
    86      }
    87
    88      UA_StatusCode res = UA_Client_recv(connection, response, timeout);
    89      if(res == UA_STATUSCODE_GOODNONCRITICALTIMEOUT)
    90          UA_fakeSleep(timeout);
    91      else
    92          UA_fakeSleep(UA_Client_recvSleepDuration);
    93      UA_Client_recvSleepDuration = 0;
    94      return res;
    95  }
